import { importProvidersFrom } from '@angular/core';
import { BrowserAnimationsModule } from '@angular/platform-browser/animations';
import { applicationConfig, type Preview } from '@storybook/angular';
import { setCompodocJson } from '@storybook/addon-docs/angular';
// Generated by Compodoc before every `ng:storybook` / `ng:build-storybook`
// run (see `compodocArgs` in angular.json); gitignored.
import docJson from './documentation.json';
import { keepComponentApiArgTypes, sanitizeCompodocJson } from './compodoc';

setCompodocJson(sanitizeCompodocJson(docJson));

const preview: Preview = {
  argTypesEnhancers: [keepComponentApiArgTypes],
  decorators: [
    applicationConfig({
      providers: [importProvidersFrom(BrowserAnimationsModule)],
    }),
  ],
  parameters: {
    docs: {},
    backgrounds: {
      grid: {
        disable: false,
      },
      disabled: true,
    },
    controls: {
      sort: 'requiredFirst',
    },
    options: {
      storySort: {
        // Without this the sidebar falls back to whatever order the builder
        // indexes files in. That currently reads alphabetically here, but only
        // because every component sits in its own flat directory — moving one
        // file would silently reorder the tree. Sorting explicitly keeps it put
        // and keeps the three Storybooks comparable. `includeNames` stays at its
        // default, so this orders sections and components only and leaves each
        // component's stories in declaration order.
        method: 'alphabetical',
        order: [
          'Foundation',
          'Motion',
          'Navigation',
          'Data Entry',
          'Data Display',
          'Feedback',
          'Others',
          'Internal',
          'V1',
        ],
      },
    },
  },
};

export default preview;
